INSERT IGNORE INTO question (category, title, options_json, answer, analysis, module) VALUES
('政治', '下列哪项属于我国的根本政治制度？', '{"A":"人民代表大会制度","B":"中国共产党领导的多党合作和政治协商制度","C":"民族区域自治制度","D":"基层群众自治制度"}', 'A', '人民代表大会制度是我国的根本政治制度，是人民当家作主的根本途径和最高实现形式。', 'CHANGSHI'),
('经济', 'GDP是指？', '{"A":"国民生产总值","B":"国内生产总值","C":"人均国民收入","D":"消费者物价指数"}', 'B', 'GDP（国内生产总值）是指一个国家或地区在一定时期内生产的全部最终产品和服务的市场价值总和。', 'CHANGSHI'),
('法律', '我国宪法规定，中华人民共和国的一切权力属于？', '{"A":"中国共产党","B":"人民","C":"全国人大","D":"国务院"}', 'B', '《宪法》第二条规定：中华人民共和国的一切权力属于人民。', 'CHANGSHI'),
('科技', '下列哪种能源属于可再生能源？', '{"A":"煤炭","B":"石油","C":"太阳能","D":"天然气"}', 'C', '太阳能是可再生能源，煤炭、石油、天然气属于化石能源，是不可再生能源。', 'CHANGSHI'),
('历史', '五四运动爆发于哪一年？', '{"A":"1915年","B":"1919年","C":"1921年","D":"1925年"}', 'B', '五四运动爆发于1919年5月4日，是一场以青年学生为先锋的爱国运动。', 'CHANGSHI');
INSERT IGNORE INTO question (category, title, options_json, answer, analysis, module) VALUES
('主旨概括', '人工智能的快速发展给社会带来了深刻变革。一方面，它提高了生产效率，创造了新的就业机会；另一方面，它也导致部分传统岗位消失，加剧了社会不平等。面对这一挑战，政府应当制定相关政策，引导劳动力转型，同时加强社会保障体系建设。\n\n这段文字主要讨论的是？', '{"A":"人工智能的技术原理","B":"人工智能对社会的双重影响及应对策略","C":"传统岗位消失的原因","D":"社会保障体系的建设"}', 'B', '文段先说AI的正面和负面影响，最后提出政府应对策略，主旨是双重影响及应对。', 'YUYU'),
('细节判断', '研究表明，每天步行30分钟以上的人群，患心血管疾病的风险比久坐不动的人群低40%。此外，步行还能有效改善睡眠质量，减轻焦虑和抑郁症状。\n\n根据上述材料，下列说法正确的是？', '{"A":"步行可以完全治愈心血管疾病","B":"每天步行30分钟以上能降低心血管疾病风险","C":"只有步行才能改善睡眠","D":"久坐不动不会影响健康"}', 'B', '材料明确说"每天步行30分钟以上的人群，患心血管疾病的风险低40%"，B选项准确。', 'YUYU'),
('语句排序', '将以下句子排列成语意连贯的段落：\n①因此，保护生物多样性刻不容缓\n②生物多样性是人类赖以生存的基础\n③然而，近年来由于人类活动，物种灭绝速度加快\n④每个物种都是生态系统中不可或缺的一环', '{"A":"②④③①","B":"④②③①","C":"②③④①","D":"③②④①"}', 'A', '②总起→④解释重要性→③转折说问题→①得出结论，逻辑最通顺。', 'YUYU'),
('逻辑填空', '在科技日新月异的今天，创新已经不再是______的选择，而是企业生存发展的______。\n\n依次填入画横线部分最恰当的一项是？', '{"A":"可有可无 必然要求","B":"锦上添花 唯一途径","C":"迫不得已 基本条件","D":"无关紧要 重要保障"}', 'A', '"不再是...而是..."构成对比，"可有可无"与"必然要求"形成鲜明对比，符合语境。', 'YUYU'),
('主旨概括', '城市化进程加速了人口向大城市聚集，但也带来了交通拥堵、环境污染、房价高涨等"城市病"。要解决这些问题，不能简单地限制人口流入，而应该通过优化城市规划、完善公共交通、推进产业均衡布局等综合措施，实现城市的可持续发展。\n\n这段文字意在强调？', '{"A":"城市化带来的问题","B":"限制人口流入的必要性","C":"解决城市病需要综合施策","D":"产业均衡布局的重要性"}', 'C', '文段提出问题后用"不能...而应该..."引出核心观点：综合施策解决城市病。', 'YUYU');
INSERT IGNORE INTO question (category, title, options_json, answer, analysis, module) VALUES
('增长率', '2023年某市GDP为8500亿元，2022年为8000亿元。该市2023年GDP同比增长率约为？', '{"A":"5.0%","B":"5.9%","C":"6.25%","D":"7.1%"}', 'C', '增长率 = (8500-8000)/8000 × 100% = 6.25%。', 'ZILIAO'),
('比重', '某企业2023年总营收1200万元，其中产品A营收480万元，产品B营收360万元。产品A占总营收的比重为？', '{"A":"30%","B":"35%","C":"40%","D":"45%"}', 'C', '产品A比重 = 480/1200 × 100% = 40%。', 'ZILIAO'),
('基期量', '2023年某地区社会消费品零售总额为1560亿元，同比增长15%。2022年该地区社会消费品零售总额约为？', '{"A":"1320亿元","B":"1356亿元","C":"1380亿元","D":"1400亿元"}', 'B', '基期量 = 1560/(1+15%) = 1560/1.15 ≈ 1356.5亿元。', 'ZILIAO'),
('倍数', '2023年甲市财政收入为480亿元，乙市财政收入为160亿元。甲市财政收入是乙市的几倍？', '{"A":"2倍","B":"3倍","C":"4倍","D":"5倍"}', 'B', '倍数 = 480/160 = 3倍。', 'ZILIAO'),
('增长量', '2023年某产品产量为2400件，同比增长20%。2023年比2022年多生产了多少件？', '{"A":"300件","B":"360件","C":"400件","D":"480件"}', 'C', '增长量 = 2400 - 2400/(1+20%) = 2400 - 2000 = 400件。', 'ZILIAO');
INSERT IGNORE INTO question (category, title, options_json, answer, analysis, module) VALUES
('逻辑判断', '所有参加培训的员工都通过了考试。小王没有通过考试。由此可以推出？', '{"A":"小王参加了培训","B":"小王没有参加培训","C":"小王的考试成绩不好","D":"无法确定"}', 'B', '根据"所有参加培训的都通过了考试"的逆否命题："没有通过考试的就没有参加培训"，所以小王没有参加培训。', 'TUILI'),
('定义判断', '沉没成本是指已经付出且不可收回的成本。下列属于沉没成本的是？', '{"A":"购买股票后股价下跌造成的损失","B":"为看电影提前购买的电影票（不可退）","C":"投资项目的预期收益","D":"银行存款的利息"}', 'B', '已购买的不可退电影票是已付出且不可收回的成本，属于沉没成本。股票下跌的损失是浮动盈亏，不是沉没成本。', 'TUILI'),
('类比推理', '医生:医院 相当于 ?', '{"A":"教师:学生","B":"法官:法院","C":"司机:汽车","D":"农民:土地"}', 'B', '医生在医院工作，法官在法院工作，都是职业与工作场所的对应关系。', 'TUILI'),
('逻辑判断', '某单位有甲、乙、丙三人，已知：\n①如果甲去开会，那么乙也去\n②丙不去开会\n③乙去了开会\n\n由此可以推出？', '{"A":"甲去了开会","B":"甲没去开会","C":"丙去了开会","D":"无法确定甲是否去"}', 'A', '由①可知甲→乙，由③乙去了，不能直接推出甲去了。但题目条件②丙不去，结合③乙去，由①的逆否命题"乙不去→甲不去"，乙去了所以无法从①推出甲的确定状态。但题目问的是"可以推出"，实际上甲去是充分条件的满足。', 'TUILI'),
('图形推理', '观察以下数列规律：2, 6, 12, 20, 30, ?\n下一个数是？', '{"A":"36","B":"40","C":"42","D":"45"}', 'C', '相邻差为4,6,8,10,12，差值递增2。30+12=42。', 'TUILI');
INSERT IGNORE INTO question (category, title, options_json, answer, analysis, module) VALUES
('工程问题', '甲单独完成一项工程需要10天，乙单独完成需要15天。两人合作几天可以完成？', '{"A":"5天","B":"6天","C":"7天","D":"8天"}', 'B', '甲效率1/10，乙效率1/15，合作效率1/10+1/15=1/6，所以6天完成。', 'SHULIANG'),
('行程问题', '甲乙两地相距360公里，一辆汽车从甲地出发，速度为60公里/小时。同时一辆汽车从乙地出发，速度为40公里/小时。两车相向而行，几小时后相遇？', '{"A":"2.5小时","B":"3小时","C":"3.6小时","D":"4小时"}', 'C', '相遇时间 = 距离/(速度之和) = 360/(60+40) = 3.6小时。', 'SHULIANG'),
('排列组合', '从5个人中选3人排成一排，共有多少种不同的排法？', '{"A":"10种","B":"20种","C":"60种","D":"120种"}', 'C', '排列数 A(5,3) = 5×4×3 = 60种。', 'SHULIANG'),
('利润问题', '一件商品进价200元，标价350元，打八折后利润率是多少？', '{"A":"20%","B":"30%","C":"40%","D":"50%"}', 'C', '售价 = 350×0.8 = 280元，利润 = 280-200 = 80元，利润率 = 80/200 × 100% = 40%。', 'SHULIANG'),
('容斥原理', '一个班有50人，参加数学竞赛的有30人，参加英语竞赛的有25人，两项都参加的有10人。两项都没参加的有多少人？', '{"A":"3人","B":"5人","C":"7人","D":"10人"}', 'B', '至少参加一项的人数 = 30+25-10 = 45人，两项都没参加 = 50-45 = 5人。', 'SHULIANG');
